from author import C,S,P,V
c=C('二次型与坐标变换')
S(c,'二次表达式也有矩阵',[
 P('先看两个变量的二次表达式，二倍 x 平方，加二倍 x y，再加二倍 y 平方。给平面上每个位置代入 x 和 y，就得到一个高度，所有位置合起来形成一张曲面。只含二次项的这种齐次二次表达式叫二次型。这里没有一次项和常数项，因此把所有变量同时乘 k，函数值会乘 k 的平方。',V('surface',A=[[2,1],[1,2]],phase='bowl'),[r'f(x,y)=2x^2+2xy+2y^2',r'f(k\mathbf{x})=k^2f(\mathbf{x})'],['平面坐标决定曲面的高度','二次型只包含齐次二次项'],12),
 P('它可以写成列向量的转置，乘对称矩阵，再乘列向量。平方项系数放在主对角线上，交叉项系数要平分到对称的两个位置，因为相乘展开会把它们加回来。所以二倍 x y 对应两处各放一，而不是两处都放二。实二次型总能唯一对应一张实对称矩阵，使用这个约定以后，矩阵性质就能帮助研究曲面。',V('matrix',A=[[2,1],[1,2]],operation='quadratic'),[r'f(\mathbf{x})=\mathbf{x}^TA\mathbf{x}',r'a_{12}=a_{21}=1'],['平方项放对角线','交叉项系数分到两个对称位置'],8)],['6.1-二次型及矩阵'])
S(c,'沿特征方向旋转坐标轴',[
 P('从上方看同样高度的点，会得到一圈圈椭圆。它们的长短轴没有沿原来的横纵坐标，所以原公式出现 x y 交叉项。现在把坐标方向换到单位特征向量上，椭圆的轴就和新坐标对齐。曲面本身没有被换成另一张曲面，只是用新的坐标来描述相同的位置。图中转动的是坐标框架，不要把它误读为在改变原函数。',V('quadratic',A=[[2,1],[1,2]],phase='rotate'),[r'\mathbf{x}=Q\mathbf{y}',r'f=\mathbf{y}^T(Q^TAQ)\mathbf{y}'],['曲面固定，改变描述它的坐标','新轴选择单位特征方向'],14),
 P('本例 Q 的两列对应特征值三和一，代入以后，二次型成为三倍 u 平方加 v 平方，交叉项消失。这个只有平方项的形式叫标准形。用正交变换求标准形，可以照四步进行：写对称矩阵，求特征值，选单位正交特征向量作为 Q 的列，再按同样顺序写出对角系数。最后也可以代回原表达式核对。',V('quadratic',A=[[2,1],[1,2]],phase='standard'),[r'Q^TAQ=\operatorname{diag}(3,1)',r'f=3u^2+v^2'],['正交标准形的系数是特征值','Q 的列与系数顺序一致'],12)],['6.2-正交法化标准形'])
S(c,'标准形和规范形不一样',[
 P('标准形只要求没有交叉项，平方项前可以是三、一等数。若继续允许一般可逆的坐标缩放，就能把非零系数的绝对值调成一，只留下正一、负一和零，这叫实二次型的规范形。本例把 u 再按根号三缩放，就从三倍 u 平方加 v 平方，变成 s 平方加 t 平方。这个额外缩放通常不是正交变换。',V('quadratic',A=[[3,0],[0,1]],phase='normalize'),[r'f=3u^2+v^2\longrightarrow s^2+t^2',r'u=s/\sqrt3,\quad v=t'],['标准形允许任意实对角系数','规范形只保留正一、负一、零'],12),
 P('规范形里正平方项个数叫正惯性指数，负平方项个数叫负惯性指数，二者之和是二次型的秩。改变可逆坐标不会改变这两个个数，这就是惯性定律。它们记录曲面具有多少个向上、向下和变平的独立方向。不能把某一组坐标里对角线上有几个正数，直接当作惯性指数，除非已经得到相应的对角形式。',V('surface',A=[[1,0],[0,-1]],phase='saddle'),[r'\text{正指数 }p,\quad\text{负指数 }q',r'r(A)=p+q'],['惯性看正负平方项的个数','零系数对应平的方向'],12)],['6.2-标准形与规范形','6.2-正负惯性指标'])
S(c,'合同与相似要分开判断',[
 P('一般可逆换元写成 x 等于 C 乘 y，代入二次型，新的对称矩阵是 C 的转置乘 A 再乘 C。这样的两张矩阵称为合同。这里左边是转置，不是逆。对于实对称矩阵，同尺寸并且正负惯性指数相同，就是合同的判据。合同保留这些符号个数和秩，但不要求每个特征值的具体大小相同。',V('quadratic',A=[[3,0],[0,1]],phase='normalize'),[r'B=C^TAC,\quad C\text{可逆}',r'\text{实对称同尺寸：惯性相同}\iff\text{合同}'],['合同来自二次型可逆换元','左边是 C 的转置'],12),
 P('相似描述线性算子的换基，保留特征值；合同描述二次型的换元，保留惯性。例如对角线三和一，与单位矩阵，实合同却不相似，因为特征值不同。若 C 恰好正交，转置等于逆，那么这一次正交变换同时具有相似和合同的表达。正是这个特殊联系，让实对称矩阵的对角化能直接用来整理二次型。',V('matrix',A=[[3,0],[0,1]],B=[[1,0],[0,1]],operation='congruence'),[r'C^T=C^{-1}\quad\text{仅在正交时}',r'\operatorname{diag}(3,1)\sim_{\rm cong}I'],['合同一般不保留特征值大小','正交变换把两种关系连接起来'],8)],['6.1-矩阵合同','6.2-合同判定'])
S(c,'练习：交叉项应该填几',[
 P('二次型是 x 平方加四倍 x y，再加三倍 y 平方。请写出它对应的实对称矩阵。主对角线的两个数分别来自哪里？两个非对角位置应该填四，还是各填二？你可以反过来，把 x 的转置乘矩阵再乘 x 展开，看交叉项最后被加了几次。请独立思考四秒。',V('matrix',A=[[1,'?'],['?',3]],operation='question'),[r'f=x^2+4xy+3y^2'],['交叉项会从两个位置各出现一次','矩阵必须对称'],0)],['6.1-练习'],kind='question',answer='对称矩阵为[[1,2],[2,3]]，非对角线各填2。')
S(c,'答案：四要分到两边',[
 P('两个非对角位置各填二。展开时，左上角贡献 x 平方，右下角贡献三倍 y 平方，而两个对称位置分别贡献二倍 x y，加起来才是四倍 x y。若两处都填四，就会得到八倍 x y，改变原题。把矩阵展开核对，是比单独背交叉项除以二更可靠的检查方式。',V('matrix',A=[[1,2],[2,3]],operation='quadratic'),[r'\mathbf{x}^T[\,1,2;2,3\,]\mathbf{x}',r'=x^2+4xy+3y^2'],['两处各贡献 2xy','相加后才得到题目里的 4xy'],8),
 P('这张对称矩阵的行列式是负一，因此两个实特征值一正一负，曲面有向上也有向下的方向，不是一只处处向上的碗。这里先看到形状，下一章正式定义正定。二次型问题的起点是把矩阵写对，之后的特征值、正交变换和正定判断，才会建立在正确对象上，不能跳过这一步。',V('surface',A=[[1,2],[2,3]],phase='saddle'),[r'\det A=3-4=-1'],['曲面沿某些方向上升，另一些下降','下一步：正定的严格要求'],12)],['6.1-练习答案'])

c=C('正定判断与综合回顾')
S(c,'正定是一项对所有非零方向的要求',[
 P('对于实对称矩阵，如果任意非零向量代入二次型，结果都严格大于零，就叫正定。图上像一只向上的碗，原点最低，离开原点沿任何方向都会得到正高度。条件里不能包含零向量，因为它代入齐次二次型一定等于零。正定不是只检查某一条方向，也不是画面上看起来大部分位置都高于零。',V('surface',A=[[2,1],[1,2]],phase='bowl'),[r'\mathbf{x}^TA\mathbf{x}>0\quad\forall\mathbf{x}\ne0'],['任意非零向量都必须严格为正','矩阵在本课限定为实对称'],14),
 P('如果只要求不小于零，叫半正定。比如 x 平方，在 y 方向上无论走多远，高度仍是零，它有一个平的方向，所以不是正定。若既能取正值又能取负值，就是不定，对应鞍形。若所有非零方向都严格为负，则是负定。通过这些曲面比较，先认清严格大于零、不小于零和正负都有，三个要求差在哪里。',V('surface',A=[[1,0],[0,0]],phase='semidefinite'),[r'\mathbf{x}^TA\mathbf{x}\ge0:\text{半正定}',r'f(x,y)=x^2'],['半正定允许非零方向高度为零','不定同时存在正值与负值'],14)],['6.3-正定二次型与矩阵概念'])
S(c,'特征值与顺序主子式判定',[
 P('实对称矩阵可以正交化成一串平方项，系数就是特征值。因此正定等价于所有特征值都严格为正。若某个特征值为零，沿它的特征方向高度就为零；若有负特征值，沿相应方向会得到负值。本例特征值三和一都是正数，所以正定。这个判据把之前研究方向伸缩的结果，直接用于判断曲面形状。',V('quadratic',A=[[2,1],[1,2]],phase='standard'),[r'A\text{正定}\iff\lambda_i>0\quad\forall i'],['正交标准形的所有系数严格为正','对称条件保证实特征值和正交基'],10),
 P('另一个常用方法是顺序主子式：从左上角开始，依次截取一阶、二阶，直到整个矩阵，计算这些行列式。实对称矩阵正定，当且仅当它们全都严格为正。本例一阶是二，二阶是三，因此正定。这里的顺序是固定的左上角嵌套，不是任意挑几个好看的子式，也不是只算整个行列式就结束。',V('rank',A=[[2,1],[1,2]],phase='leading'),[r'\Delta_1>0,\ldots,\Delta_n>0',r'\Delta_1=2,\quad\Delta_2=3'],['顺序主子式从左上角依次截取','必须全部严格大于零'],10)],['6.3-正定判定与推论'])
S(c,'避免两个常见误判',[
 P('只看行列式为正，不足以判断正定。负的单位矩阵在二维时，行列式也是正一，但任意非零向量代入都得到负值，是负定。行列式只记录特征值的乘积，两个负数相乘同样为正。所以正定需要检查所有特征值，或者全部顺序主子式，不能从一个乘积的正负推出每一项的正负。',V('surface',A=[[-1,0],[0,-1]],phase='negative'),[r'\det(-I_2)=1>0',r'\mathbf{x}^T(-I)\mathbf{x}=-\|\mathbf{x}\|^2'],['行列式为正不是充分条件','乘积为正不代表每项为正'],12),
 P('还有一个容易混的边界：把顺序主子式全大于零，简单改成全不小于零，不能直接得到半正定判据。图中对角线上零和负一，两个顺序主子式都是零，但沿第二个坐标方向结果是负的。半正定可用所有特征值非负判断，或者检查所有主子式非负，而不只是那一串顺序主子式。保留定理的完整条件，才不会把正确规则改成错误规则。',V('surface',A=[[0,0],[0,-1]],phase='negative'),[r'A=\operatorname{diag}(0,-1)',r'\Delta_1=\Delta_2=0\ \text{仍非半正定}'],['严格正定与半正定判据不同','不能只把大于号改成大于等于号'],12)],['6.3-判据边界与推论'])
S(c,'练习：对角线为正就够了吗',[
 P('最后一题，实对称矩阵的主对角线都是一，另外两个元素都是二。它是否正定？你可以计算第二个顺序主子式，也可以试试一和负一这个向量。请注意，检查一个向量得到正值，不能证明所有方向都为正；但只要找到一个非零向量使结果不为正，就能否定正定。',V('matrix',A=[[1,2],[2,1]],operation='question'),[r'A=[\,1,2;2,1\,]'],['计算二阶顺序主子式','或寻找一个反例方向'],0)],['6.3-练习'],kind='question',answer='不是正定；行列式-3，且向量(1,-1)代入得到-2。')
S(c,'答案：一个下降方向就能否定',[
 P('它不是正定。第二个顺序主子式是一减四，等于负三，已经不符合要求。再把一和负一代入，得到一减四再加一，等于负二，也直接找到了一个非零反例。图上曲面沿这个方向下降，而另一个方向上升，是鞍形。对角线元素为正，只检查了坐标轴方向，没检查轴之间的组合方向。',V('surface',A=[[1,2],[2,1]],phase='saddle'),[r'\det A=-3',r'f(1,-1)=-2<0'],['非零反例足以否定正定','对角线只反映坐标轴方向'],12),
 P('这也提醒我们，线性代数经常研究方向怎样组合，不能只看几个孤立数字。判断之前先核对对象：是否方阵，是否实对称，变量有几个，允许怎样变换。然后再选择行列式、秩、特征值或主子式。公式不是越多越好，而是要知道当前问题需要什么信息，以及某个条件究竟能推出多强的结论。',V('quadratic',A=[[1,2],[2,1]],phase='contour'),[r'\text{先查条件，再选判据}'],['先核对对象及定理条件','用明确的反例检查错误说法'],10)],['6.3-练习答案'])
S(c,'把六章内容连成一张图',[
 P('现在回看主线。向量负责描述方向和组合，矩阵把这些组合组织成变换。行列式衡量面积倍率，非零时方阵可逆，零时发生方向压缩。秩数出独立信息，决定方程组是否有解以及有多少自由方向。特征向量找出特殊不变直线，相似对角化让各方向分别处理，正交变换在保持长度的坐标里完成这件事。',V('map'),[],['向量 → 矩阵 → 行列式与秩','方程组 → 特征值 → 正交化','二次型 → 合同与正定'],0),
 P('最后，实对称矩阵连接到二次型，特征值成为平方项系数，正负惯性告诉我们形状，正定判据检验是否所有非零方向都向上。课后建议重新手算本课的几个二阶和三阶例子，每一步都和图形对应，并练习写出定理的适用条件。遇到原文件里的概念，可以从配套索引找到对应小节，再从一个具体例子重新推回公式。',V('map'),[],['手算例子并对照动画','检查每个定理的适用条件','用知识点索引回到对应片段'],0)],['综合回顾'])
